import * as React from "react";

export function BallpitPhysics2D({ className = "w-full h-full min-h-[260px]" }: { className?: string }): React.JSX.Element {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  React.useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let w = (canvas.width = canvas.parentElement?.clientWidth ?? 600);
    let h = (canvas.height = canvas.parentElement?.clientHeight ?? 300);
    type Ball = { x: number; y: number; vx: number; vy: number; r: number; color: string };
    const colors = ["#f43f5e","#f59e0b","#3b82f6","#10b981","#8b5cf6","#ec4899"];
    const balls: Ball[] = Array.from({ length: 30 }, (_, i) => ({
      x: 40 + Math.random() * (w - 80), y: Math.random() * h / 2, vx: (Math.random() - 0.5) * 3, vy: Math.random() * 2,
      r: 10 + Math.random() * 14, color: colors[i % colors.length]
    }));
    let animId: number;
    const draw = () => {
      ctx.fillStyle = "#07080e";
      ctx.fillRect(0, 0, w, h);
      for (const b of balls) {
        b.vy += 0.2;
        b.x += b.vx; b.y += b.vy;
        if (b.x - b.r < 0) { b.x = b.r; b.vx *= -0.8; }
        if (b.x + b.r > w) { b.x = w - b.r; b.vx *= -0.8; }
        if (b.y + b.r > h) { b.y = h - b.r; b.vy *= -0.72; b.vx *= 0.97; }
        ctx.fillStyle = b.color;
        ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "rgba(255,255,255,0.25)";
        ctx.beginPath(); ctx.arc(b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.35, 0, Math.PI * 2); ctx.fill();
      }
      animId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animId);
  }, []);
  return <div className={className}><canvas ref={canvasRef} className="w-full h-full block" /></div>;
}

import * as React from "react";
import { BallpitPhysics2D } from "./ballpit-physics-2d";

export default function BallpitPhysics2DDemo(): React.JSX.Element {
  return (
    <div className="relative flex min-h-[480px] w-full overflow-hidden rounded-2xl bg-neutral-950 border border-neutral-800">
      {/* Background canvas layer */}
      <BallpitPhysics2D className="absolute inset-0 h-full w-full" />

      {/* Foreground content layer */}
      <div className="relative z-10 flex h-full w-full flex-col items-center justify-center p-8 text-center my-auto">
        <span className="rounded-full border border-white/15 bg-white/10 px-3.5 py-1 text-xs font-mono font-medium text-neutral-300 backdrop-blur-md">
          Ambient Canvas Engine
        </span>
        <h2 className="mt-4 text-3xl sm:text-5xl font-bold tracking-tight text-white">
          Ballpit Physics 2D
        </h2>
        <p className="mt-3 max-w-md text-sm sm:text-base text-neutral-400">
          Hardware-accelerated ambient visuals that react seamlessly to viewport and pointer interactions.
        </p>
      </div>
    </div>
  );
}
